<script lang="ts">import{KeyRound,Save}from'@lucide/svelte';import Password from'./PasswordField.svelte';import{changeBmsPassword,hasBmsSession}from'$lib/services/bms-api';let form=$state({oldPassword:'',newPassword:'',confirmPassword:''});let show=$state({old:false,new:false,confirm:false});let saving=$state(false);let error=$state('');let notice=$state('');async function submit(){error='';if(!form.oldPassword.trim()){error='Old password is required.';return}if(form.newPassword.length<12){error='New password must be at least 12 characters.';return}if(form.newPassword!==form.confirmPassword){error='Passwords do not match.';return}saving=true;try{if(hasBmsSession())await changeBmsPassword(form.oldPassword,form.newPassword);notice=hasBmsSession()?'Password changed. Please sign in again.':'Password payload is valid; authenticate to submit it.';form={oldPassword:'',newPassword:'',confirmPassword:''}}catch(e){error=e instanceof Error?e.message:'Failed to change password.'}finally{saving=false}}</script>
<section class="page"><div class="head"><h2><KeyRound size={23}/>Account Settings</h2><p>Change Administrator Password</p></div>{#if notice}<div class="notice">{notice}</div>{/if}{#if error}<div class="error">{error}</div>{/if}<section class="card"><h3>Change password</h3><form onsubmit={(e)=>{e.preventDefault();submit()}}><Password label="Old password" bind:value={form.oldPassword} bind:visible={show.old}/><Password label="New password" bind:value={form.newPassword} bind:visible={show.new}/><Password label="Confirm new password" bind:value={form.confirmPassword} bind:visible={show.confirm}/><button type="submit" disabled={saving}><Save size={16}/>{saving?'Saving…':'Save Changes'}</button></form></section></section>
<style>.head h2{display:flex;align-items:center;gap:9px;margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 19px;color:#718096;font-size:16px}.card{max-width:610px;overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.card h3{margin:0;padding:16px 19px;border-bottom:1px solid #edf0f4;color:#31415c;font-size:16px;font-weight:500}form{display:grid;gap:16px;padding:19px}label{display:grid;gap:6px;color:#536078;font-size:13px}label div{position:relative}input{width:100%;height:40px;padding:0 42px 0 11px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;font:inherit}label button{position:absolute;top:3px;right:3px;display:grid;width:34px;height:34px;place-items:center;border:0;color:#65738a;background:transparent;cursor:pointer}form>button{display:inline-flex;align-items:center;justify-content:center;gap:7px;width:max-content;height:39px;padding:0 14px;border:0;border-radius:8px;color:#fff;background:#1749ad;font:inherit;cursor:pointer}.notice,.error{max-width:610px;margin-bottom:13px;padding:10px 12px;border-radius:8px;font-size:13px}.notice{color:#28784e;background:#f2fbf5;border:1px solid #cae7d5}.error{color:#b42318;background:#fff1f0;border:1px solid #f3cac6}@media(max-width:650px){form>button{width:100%}}</style>
